import { MetadataRoute } from 'next';

// Was: name 'pastorOs', and icons pointing at https://picsum.photos/seed/… —
// random placeholder photos on a third party. Chrome will not offer to install
// an app whose icons are cross-origin randoms, and they cannot be cached for
// the offline shell, so "installable" was never actually true.
//
// Icons are generated by scripts/generate-pwa-icons.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'churchOs — Church management',
    short_name: 'churchOs',
    description:
      'Multi-tenant church management: attendance, ushers, members, giving and SMS.',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    display_override: ['standalone', 'minimal-ui'],
    orientation: 'portrait',
    background_color: '#F0E6D3',
    theme_color: '#1E1208',
    lang: 'en',
    dir: 'ltr',
    categories: ['productivity', 'lifestyle'],
    icons: [
      {
        src: '/icons/icon-192.png',
        sizes: '192x192',
        type: 'image/png',
        purpose: 'any',
      },
      {
        src: '/icons/icon-512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'any',
      },
      // Separate entries, not a space-separated "any maskable" string: a single
      // icon declared as both lets the launcher apply the mask to the
      // any-purpose asset, clipping the mark.
      {
        src: '/icons/maskable-192.png',
        sizes: '192x192',
        type: 'image/png',
        purpose: 'maskable',
      },
      {
        src: '/icons/maskable-512.png',
        sizes: '512x512',
        type: 'image/png',
        purpose: 'maskable',
      },
    ],
    shortcuts: [
      {
        name: 'Usher check-in',
        short_name: 'Check-in',
        description: 'Open the usher portal',
        url: '/',
      },
    ],
  };
}
